let adminRegisterMode=false;
const ADMIN_CREDENTIAL_KEY="hokego_admin_credential_v1";
const ADMIN_SESSION_KEY="hokego_admin_session_v1";
function toggleAdminRegister(){
 adminRegisterMode=!adminRegisterMode;
 const title=$("adminGateTitle");
 const sub=document.querySelector("#adminLogin .admin-login-modal-sub");
 const submit=$("adminSubmitButton");
 const toggle=$("adminRegisterToggle");
 if(adminRegisterMode){
  title.textContent="管理者パスワード登録";
  sub.textContent="この端末で使用する管理者情報を登録します";
  submit.textContent="登録して管理画面へ";
  toggle.textContent="登録済みの方：ログインに戻る";
  $("adminPassword").setAttribute("autocomplete","new-password");
 }else{
  title.textContent="管理者ログイン";
  sub.textContent="秘密の指令室に入室します";
  submit.textContent="ログイン";
  toggle.textContent="初めて利用する場合：管理者パスワードを登録";
  $("adminPassword").setAttribute("autocomplete","current-password");
 }
 $("adminLoginMessage").textContent="";
}
async function adminPasswordDigest(email,password){
 const bytes=new TextEncoder().encode(email.toLowerCase()+"|"+password);
 const hash=await crypto.subtle.digest("SHA-256",bytes);
 return Array.from(new Uint8Array(hash)).map(b=>b.toString(16).padStart(2,"0")).join("");
}
function enterAdminDashboard(){
 $("adminLogin").classList.add("hidden");
 $("adminDashboard").classList.remove("hidden");
 $("adminModulePanel").classList.add("hidden");
 try{localStorage.setItem(ADMIN_SESSION_KEY,"1")}catch(e){}
}
async function submitAdminLogin(){
 const email=$("adminEmail").value.trim().toLowerCase();
 const password=$("adminPassword").value;
 const msg=$("adminLoginMessage");
 if(!email || !password){
  msg.textContent="メールアドレスとパスワードを入力してください。";
  return;
 }
 if(!/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(email)){
  msg.textContent="メールアドレスの形式を確認してください。";
  return;
 }
 if(password.length<6){
  msg.textContent="パスワードは6文字以上で設定してください。";
  return;
 }
 const submit=$("adminSubmitButton");
 submit.disabled=true;
 try{
  const saved=localStorage.getItem(ADMIN_CREDENTIAL_KEY);
  const digest=await adminPasswordDigest(email,password);
  if(adminRegisterMode){
   if(saved){
    msg.textContent="この端末には管理者情報が登録済みです。ログインしてください。";
    return;
   }
   localStorage.setItem(ADMIN_CREDENTIAL_KEY,JSON.stringify({email,digest,createdAt:new Date().toISOString()}));
   adminRegisterMode=false;
   enterAdminDashboard();
   return;
  }
  if(!saved){
   msg.textContent="管理者情報が未登録です。下の「管理者パスワードを登録」から初回登録してください。";
   return;
  }
  const credential=JSON.parse(saved);
  if(credential.email!==email || credential.digest!==digest){
   msg.textContent="メールアドレスまたはパスワードが違います。";
   return;
  }
  enterAdminDashboard();
 }catch(e){
  msg.textContent="このブラウザでは登録情報を保存できません。ブラウザ設定をご確認ください。";
 }finally{
  submit.disabled=false;
 }
}
function restoreAdminSession(){
 try{
  if(localStorage.getItem(ADMIN_SESSION_KEY)==="1"){
   $("adminLogin").classList.add("hidden");
   $("adminDashboard").classList.remove("hidden");
  }
 }catch(e){}
}
window.addEventListener("DOMContentLoaded",restoreAdminSession);
if(document.readyState!=="loading") restoreAdminSession();


const ADMIN_MODULES={
 users:["ユーザー管理","管理者・教員・利用者のアカウント管理を行う画面です。ユーザー一覧、権限、登録状態などの管理機能をここに実装します。"],
 questions:["問題データ管理","保健クイズの問題・選択肢・正解・解説を追加、編集、削除する機能を配置します。既存の問題データはこの段階では変更していません。"],
 materials:["授業資料の管理","授業資料の追加、PDF・PowerPointの登録、授業回ごとの整理を行う機能を配置します。"],
 settings:["システム設定","アプリ全体の表示・運用設定、管理者設定などを行う画面です。"],
 backup:["データの保存・復元","アプリのデータを書き出して保存し、必要時に復元する機能を配置します。実際のバックアップ処理は次段階で接続します。"],
 usage:["利用状況の確認","クイズの利用状況、アクセス数、学習状況などを確認する画面です。集計データとの接続は次段階で行います。"]
};
function openAdminModule(key){
 const item=ADMIN_MODULES[key];if(!item)return;
 $("adminModuleTitle").textContent=item[0];
 if(key==="users"){
  $("adminModuleBody").innerHTML='<div id="adminUserManager"></div>';
  renderAdminUsers();
 }else{
  $("adminModuleBody").textContent=item[1];
 }
 $("adminModulePanel").classList.remove("hidden");
}
const ADMIN_USERS_KEY="hokego_admin_users_v1";
function getAdminUsers(){try{return JSON.parse(localStorage.getItem(ADMIN_USERS_KEY)||"[]")}catch(e){return []}}
function saveAdminUsers(users){localStorage.setItem(ADMIN_USERS_KEY,JSON.stringify(users))}
function userEscape(v){return String(v??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]))}
function renderAdminUsers(){
 const root=$("adminUserManager");if(!root)return;
 const users=getAdminUsers();
 root.innerHTML=`
  <div class="user-note">管理者と、登録を希望する教員のみを管理します。生徒のアカウント登録は不要です。登録情報はこの端末のブラウザ内に保存されます。</div>
  <form class="user-form" onsubmit="addAdminUser(event)">
   <div><label for="newUserName">氏名</label><input id="newUserName" required maxlength="40" placeholder="例：山田 花子"></div>
   <div><label for="newUserEmail">メールアドレス</label><input id="newUserEmail" type="email" required maxlength="120" placeholder="例：user@example.jp"></div>
   <div><label for="newUserRole">権限</label><select id="newUserRole"><option>教員</option><option>管理者</option></select></div>
   <button type="submit">＋ ユーザー登録</button>
  </form>
  <div style="display:flex;justify-content:space-between;align-items:center;margin:12px 0"><strong>登録ユーザー：${users.length}名</strong><span class="user-note">利用停止中も削除せず保管できます</span></div>
  <div class="user-list">${users.length?users.map((u,i)=>`<div class="user-row">
   <div><strong>${userEscape(u.name)}</strong><small>${userEscape(u.email)}</small></div>
   <div><label>権限</label><select aria-label="権限" onchange="changeAdminUserRole(${i},this.value)"><option ${u.role==="管理者"?"selected":""}>管理者</option><option ${u.role==="教員"?"selected":""}>教員</option></select></div>
   <div class="user-status ${u.active===false?"off":""}">${u.active===false?"利用停止中":"利用中"}</div>
   <button type="button" onclick="toggleAdminUser(${i})">${u.active===false?"利用再開":"利用停止"}</button>
   <button type="button" class="danger" onclick="deleteAdminUser(${i})">削除</button>
  </div>`).join(""):'<p class="user-note">ユーザーはまだ登録されていません。上のフォームから登録してください。</p>'}</div>`;
}
function addAdminUser(ev){
 ev.preventDefault();
 const name=$("newUserName").value.trim(),email=$("newUserEmail").value.trim().toLowerCase(),role=$("newUserRole").value;
 if(!["管理者","教員"].includes(role)){alert("登録できる権限は管理者・教員のみです。");return;}
 if(!name||!email)return;
 const users=getAdminUsers();
 if(users.some(u=>u.email.toLowerCase()===email)){alert("このメールアドレスは既に登録されています。");return}
 users.push({name,email,role,active:true,createdAt:new Date().toISOString()});
 saveAdminUsers(users);renderAdminUsers();
}
function changeAdminUserRole(i,role){if(!["管理者","教員"].includes(role))return;const users=getAdminUsers();if(!users[i])return;users[i].role=role;saveAdminUsers(users);renderAdminUsers()}
function toggleAdminUser(i){const users=getAdminUsers();if(!users[i])return;users[i].active=users[i].active===false;saveAdminUsers(users);renderAdminUsers()}
function deleteAdminUser(i){const users=getAdminUsers();if(!users[i])return;if(!confirm("このユーザーを削除します。よろしいですか？"))return;users.splice(i,1);saveAdminUsers(users);renderAdminUsers()}
