const LESSON_MATERIALS = [];
function renderMaterials(){
 const root=$("lessonMaterials");
 const hasMaterials=LESSON_MATERIALS.some(lesson=>(lesson.files||[]).some(file=>file.url));
 if(!hasMaterials){
  root.innerHTML='<div class="materials-empty"><strong>授業資料はここに表示されます</strong></div>';
  return;
 }
 root.innerHTML=LESSON_MATERIALS.filter(lesson=>(lesson.files||[]).some(file=>file.url)).map((lesson,i)=>{
  const files=(lesson.files||[]).filter(f=>f.url).map(f=>`<a class="file-link ${f.type==='ppt'?'ppt':''}" href="${f.url}" target="_blank" rel="noopener" ${f.download?'download':''}>${f.type==='ppt'?'PowerPoint':'PDF'}を${f.type==='pdf'?'閲覧・':''}ダウンロード</a>`).join('');
  return `<article class="lesson-card"><div><div class="lesson-title">${lesson.title}</div><div class="lesson-subtitle">${lesson.description||'授業資料'}</div></div><div class="lesson-files">${files}</div></article>`;
 }).join('');
}
