(function(){
  function startHokeGoOpening(){
    var splash=document.getElementById('hokegoSplash');
    if(!splash)return;
    document.body.classList.add('opening-active','splash-active');
    // Icon remains visible for 2 seconds, then fades away.
    window.setTimeout(function(){
      splash.classList.add('is-hidden');
    },2000);
    // Home screen zooms out smoothly over 1 second as the icon fades.
    window.setTimeout(function(){
      document.body.classList.remove('splash-active');
      document.body.classList.add('opening-home-zoom');
    },2500);
    window.setTimeout(function(){
      if(splash.parentNode)splash.parentNode.removeChild(splash);
      document.body.classList.remove('opening-active','opening-home-zoom');
    },3500);
  }
  if(document.readyState==='loading'){
    document.addEventListener('DOMContentLoaded',startHokeGoOpening,{once:true});
  }else{
    startHokeGoOpening();
  }
})();


